import React from 'react';
import './Forum.css';

const Forum = () => {
    const forums = [
        { id: 1, name: "General Discussion", description: "Talk about anything and everything." },
        { id: 2, name: "News", description: "Stay updated with the latest news." },
        { id: 3, name: "Support", description: "Get help and support for your issues." },
    ];

    return (
        <div className="forum-list">
            <h2>Forums</h2>
            <ul>
                {forums.map((forum) => (
                    <li key={forum.id} className="forum-item">
                        <h3>{forum.name}</h3>
                        <p>{forum.description}</p>
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default Forum;
